#include "four_dim_tensor_matrix_multiplication_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/platform/platform_ascendc.h"
#include "tiling/tiling_api.h"

using namespace matmul_tiling;

namespace optiling {
/**
  * @brief  Generate tiling for 4D tensor-matrix multiplication by flattening A to 2D.
  *         A: (b, i, j, l) -> A2D: (b*i*j, l); B: (l, k); C2D: (b*i*j, k) -> reshape back to (b,i,j,k) in PyTorch layer.
  */
static ge::graphStatus TilingFunc(gert::TilingContext *context)
{
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    auto shape_a = context->GetInputTensor(0)->GetOriginShape(); // (b,i,j,l)
    auto shape_b = context->GetInputTensor(1)->GetOriginShape(); // (l,k)

    int32_t b = static_cast<int32_t>(shape_a.GetDim(0));
    int32_t i = static_cast<int32_t>(shape_a.GetDim(1));
    int32_t j = static_cast<int32_t>(shape_a.GetDim(2));
    int32_t l = static_cast<int32_t>(shape_a.GetDim(3));
    int32_t k = static_cast<int32_t>(shape_b.GetDim(1));

    int32_t M = b * i * j; // flatten batch dims
    int32_t N = k;
    int32_t K = l;

    MultiCoreMatmulTiling cubeTiling(ascendcPlatform);
    cubeTiling.SetDim(2); // demo: allow up to 2 cores
    cubeTiling.SetAType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
    cubeTiling.SetBType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
    cubeTiling.SetCType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
    cubeTiling.SetShape(M, N, K);
    cubeTiling.SetSingleShape(M, N, K);
    cubeTiling.SetOrgShape(M, N, K);
    cubeTiling.SetBufferSpace(-1, -1, -1);

    FourDimTensorMatrixMultiplicationCustomTilingData tiling;
    if (cubeTiling.GetTiling(tiling.cubeTilingData) == -1) {
        return ge::GRAPH_FAILED;
    }

    int32_t coreNum = 1;
    if (cubeTiling.GetCoreNum() > 0) {
        coreNum = cubeTiling.GetCoreNum();
    }

    context->SetBlockDim(coreNum);
    context->SetTilingKey(coreNum);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t userWorkspaceSize = 0;
    size_t systemWorkspaceSize = static_cast<size_t>(ascendcPlatform.GetLibApiWorkSpaceSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = userWorkspaceSize + systemWorkspaceSize;

    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

